class TextEditor {
    private final StringBuilder left = new StringBuilder();
    private final StringBuilder rightReversed = new StringBuilder();

    public TextEditor() {
    }

    public void addText(String text) {
        left.append(text);
    }

    public int deleteText(int k) {
        int deleted = Math.min(k, left.length());
        left.delete(left.length() - deleted, left.length());
        return deleted;
    }

    public String cursorLeft(int k) {
        int move = Math.min(k, left.length());
        for (int i = 0; i < move; i++) {
            rightReversed.append(left.charAt(left.length() - 1));
            left.deleteCharAt(left.length() - 1);
        }
        return lastTen();
    }

    public String cursorRight(int k) {
        int move = Math.min(k, rightReversed.length());
        for (int i = 0; i < move; i++) {
            left.append(rightReversed.charAt(rightReversed.length() - 1));
            rightReversed.deleteCharAt(rightReversed.length() - 1);
        }
        return lastTen();
    }

    private String lastTen() {
        int start = Math.max(0, left.length() - 10);
        return left.substring(start);
    }
}

class TextEditor {
    private final StringBuilder text = new StringBuilder();
    private int cursor = 0;

    public TextEditor() {
    }

    public void addText(String value) {
        text.insert(cursor, value);
        cursor += value.length();
    }

    public int deleteText(int k) {
        int deleted = Math.min(k, cursor);
        int start = cursor - deleted;
        text.delete(start, cursor);
        cursor = start;
        return deleted;
    }

    public String cursorLeft(int k) {
        cursor = Math.max(0, cursor - k);
        return lastTen();
    }

    public String cursorRight(int k) {
        cursor = Math.min(text.length(), cursor + k);
        return lastTen();
    }

    private String lastTen() {
        int start = Math.max(0, cursor - 10);
        return text.substring(start, cursor);
    }
}

class TextEditor {
    private static class Node {
        char value;
        Node prev;
        Node next;

        Node(char value) {
            this.value = value;
        }
    }

    private final Node head = new Node('\0');
    private final Node tail = new Node('\0');
    private Node cursor;

    public TextEditor() {
        head.next = tail;
        tail.prev = head;
        cursor = head;
    }

    public void addText(String text) {
        for (int i = 0; i < text.length(); i++) {
            Node node = new Node(text.charAt(i));
            insertAfter(cursor, node);
            cursor = node;
        }
    }

    public int deleteText(int k) {
        int deleted = 0;
        while (deleted < k && cursor != head) {
            Node remove = cursor;
            cursor = cursor.prev;
            unlink(remove);
            deleted++;
        }
        return deleted;
    }

    public String cursorLeft(int k) {
        while (k > 0 && cursor != head) {
            cursor = cursor.prev;
            k--;
        }
        return lastTen();
    }

    public String cursorRight(int k) {
        while (k > 0 && cursor.next != tail) {
            cursor = cursor.next;
            k--;
        }
        return lastTen();
    }

    private void insertAfter(Node prev, Node node) {
        Node next = prev.next;
        prev.next = node;
        node.prev = prev;
        node.next = next;
        next.prev = node;
    }

    private void unlink(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private String lastTen() {
        StringBuilder builder = new StringBuilder();
        Node node = cursor;
        for (int i = 0; i < 10 && node != head; i++) {
            builder.append(node.value);
            node = node.prev;
        }
        return builder.reverse().toString();
    }
}

class TextEditor {
    private char[] buffer = new char[64];
    private int gapStart = 0;
    private int gapEnd = buffer.length;

    public TextEditor() {
    }

    public void addText(String text) {
        ensureGap(text.length());
        for (int i = 0; i < text.length(); i++) {
            buffer[gapStart++] = text.charAt(i);
        }
    }

    public int deleteText(int k) {
        int deleted = Math.min(k, gapStart);
        gapStart -= deleted;
        return deleted;
    }

    public String cursorLeft(int k) {
        int move = Math.min(k, gapStart);
        for (int i = 0; i < move; i++) {
            buffer[--gapEnd] = buffer[--gapStart];
        }
        return lastTen();
    }

    public String cursorRight(int k) {
        int rightLength = buffer.length - gapEnd;
        int move = Math.min(k, rightLength);
        for (int i = 0; i < move; i++) {
            buffer[gapStart++] = buffer[gapEnd++];
        }
        return lastTen();
    }

    private void ensureGap(int needed) {
        if (gapEnd - gapStart >= needed) {
            return;
        }
        int rightLength = buffer.length - gapEnd;
        int currentLength = buffer.length - (gapEnd - gapStart);
        int newCapacity = Math.max(buffer.length * 2 + needed, currentLength + needed + 16);
        char[] next = new char[newCapacity];
        System.arraycopy(buffer, 0, next, 0, gapStart);
        int newGapEnd = newCapacity - rightLength;
        System.arraycopy(buffer, gapEnd, next, newGapEnd, rightLength);
        buffer = next;
        gapEnd = newGapEnd;
    }

    private String lastTen() {
        int start = Math.max(0, gapStart - 10);
        return new String(buffer, start, gapStart - start);
    }
}

class TextEditor {
    private static class Node {
        char value;
        int priority;
        int size = 1;
        Node left;
        Node right;

        Node(char value, int priority) {
            this.value = value;
            this.priority = priority;
        }
    }

    private Node root;
    private int cursor;
    private int seed = 123456789;

    public TextEditor() {
    }

    public void addText(String text) {
        Node[] split = split(root, cursor);
        root = merge(merge(split[0], build(text)), split[1]);
        cursor += text.length();
    }

    public int deleteText(int k) {
        int deleted = Math.min(k, cursor);
        Node[] leftAndRest = split(root, cursor - deleted);
        Node[] removedAndRight = split(leftAndRest[1], deleted);
        root = merge(leftAndRest[0], removedAndRight[1]);
        cursor -= deleted;
        return deleted;
    }

    public String cursorLeft(int k) {
        cursor = Math.max(0, cursor - k);
        return lastTen();
    }

    public String cursorRight(int k) {
        cursor = Math.min(size(root), cursor + k);
        return lastTen();
    }

    private String lastTen() {
        int start = Math.max(0, cursor - 10);
        Node[] a = split(root, start);
        Node[] b = split(a[1], cursor - start);
        StringBuilder builder = new StringBuilder();
        collect(b[0], builder);
        root = merge(a[0], merge(b[0], b[1]));
        return builder.toString();
    }

    private Node build(String text) {
        Node node = null;
        for (int i = 0; i < text.length(); i++) {
            node = merge(node, new Node(text.charAt(i), nextPriority()));
        }
        return node;
    }

    private Node[] split(Node node, int leftSize) {
        if (node == null) {
            return new Node[] {null, null};
        }
        if (size(node.left) >= leftSize) {
            Node[] parts = split(node.left, leftSize);
            node.left = parts[1];
            pull(node);
            return new Node[] {parts[0], node};
        }
        Node[] parts = split(node.right, leftSize - size(node.left) - 1);
        node.right = parts[0];
        pull(node);
        return new Node[] {node, parts[1]};
    }

    private Node merge(Node left, Node right) {
        if (left == null) {
            return right;
        }
        if (right == null) {
            return left;
        }
        if (left.priority < right.priority) {
            left.right = merge(left.right, right);
            pull(left);
            return left;
        }
        right.left = merge(left, right.left);
        pull(right);
        return right;
    }

    private void collect(Node node, StringBuilder builder) {
        if (node == null) {
            return;
        }
        collect(node.left, builder);
        builder.append(node.value);
        collect(node.right, builder);
    }

    private int size(Node node) {
        return node == null ? 0 : node.size;
    }

    private void pull(Node node) {
        node.size = 1 + size(node.left) + size(node.right);
    }

    private int nextPriority() {
        seed ^= seed << 13;
        seed ^= seed >>> 17;
        seed ^= seed << 5;
        return seed;
    }
}
